// Generated by `npm run chat:probe -- --from-trace` (T-0174) from 2026-10-14.jsonl:1 (catalog agent-ui--croupier),
// assertions narrowed by hand for T-0172. Keyless: the recorded model round replays through the real produce().
// Haiku 5.5 wrote its A2UI lines into the prose instead of calling render_surface. The fix routes them as the
// payload, so they never reach the chat as text. The recorded payload is itself invalid (its updateDataModel
// has no surfaceId), so every replayed round fails SCHEMA and the turn degrades to its prose with the codes on
// the trace; a live model gets the tool-aware repair message. `no-surface-loss` stays red for that reason: the
// model never produced a valid `ask-1`.
import { readFileSync } from 'node:fs'
import { expect, it } from 'vitest'
import { metaOf, parseProbeFixture } from '../model.ts'
import { offlineReplay } from '../trace.ts'

it('croupier-haiku-json-prose: A2UI lines in the prose are routed as the payload, never shown as chat text', async () => {
  const fixture = parseProbeFixture(readFileSync(new URL('./croupier-haiku-json-prose.json', import.meta.url), 'utf8'))
  const report = await offlineReplay(fixture, process.cwd())
  expect(report.checks.find((c) => c.check === 'no-json-as-prose')?.status).toBe('pass')
  expect(report.failed.map((c) => c.check)).toEqual(['no-surface-loss'])
  const meta = report.records[0].lines.map((l) => JSON.parse(l).a2uiMeta).find((m) => m?.trace !== undefined)
  expect(meta.trace.failureCodes).toEqual(['SCHEMA', 'TEXT_JSONL_ROUTED', 'SURFACE_DEGRADED'])
  expect(metaOf(report.records[0].lines).prose.join('\n')).not.toContain('"version"')
})
